import { test, expect } from "@playwright/test";

import { signIn, mockApi } from "./fixtures";

/**
 * User request, 13 Sep — "remove the concept of admin can generate
 * creator's invoice, invoice will be generated by creator's only". The
 * Invoices page's "New invoice" entry points (desktop header button +
 * mobile FAB) are the only raise flow left, and only a CREATOR gets them.
 * Server side: POST /invoices/bulk is CREATOR-only (invoices/routes.js)
 * and bulkCreateInvoice rejects any other role (service.test.js).
 */
test.describe("Invoices page — only a creator can raise an invoice", () => {
  for (const role of ["ADMIN", "FINANCE", "PLAN_MAKER"] as const) {
    test(`${role} has no New invoice button`, async ({ page }) => {
      await signIn(page, role);
      await mockApi(page);
      await page.goto("/invoices");
      await expect(page.getByRole("heading", { name: "Invoices" })).toBeVisible();
      await expect(page.getByRole("button", { name: "New invoice" })).toHaveCount(0);
    });
  }

  test("CREATOR still gets New invoice", async ({ page }) => {
    await signIn(page, "CREATOR");
    await mockApi(page);
    await page.goto("/invoices");
    await expect(page.getByRole("button", { name: "New invoice" }).first()).toBeVisible();
  });
});
